const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(); let state={documents:[]},page='home',filter='',category='',current=null,view='canvas',selected=null,undo=[],redo=[],linkFrom=null,focusIndex=0,detail=false,background='dark',simData=null,simSource='模拟数据',streamTimer=null,searchMode='all';
const atoms=()=>state.documents.filter(d=>d._kind==='atom'&&!d.deleted).sort((a,b)=>a.id.localeCompare(b.id)), services=()=>state.documents.filter(d=>d._kind==='service'&&!d.deleted), ideas=()=>state.documents.filter(d=>d._kind==='idea'&&!d.deleted);
const categories=()=>[...new Set(atoms().map(a=>a.category))];
let prefs=JSON.parse(localStorage.getItem('glasshouse-preferences')||'{"provider":"Gemini","model":""}');
async function api(path,data){const r=await fetch('/api/'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.error||'请求失败');return j;}
function toast(t){if($('#modal')?.open){let e=$('#modal .inline-feedback');if(!e){e=document.createElement('div');e.className='inline-feedback notice';e.setAttribute('role','status');$('#modal').appendChild(e)}e.textContent=t}$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',4500)}
async function refresh(){state=await api('state')}
async function put(doc,kind){const d=await api('save',{document:doc,kind,expected:doc._revision});const i=state.documents.findIndex(x=>x.id===d.id);if(i>=0)state.documents.splice(i,1);state.documents.unshift(d);return d}
function modal(title,body,buttons=''){const m=$('#modal');m.innerHTML=`<div class="dialoghead"><h2>${title}</h2><button onclick="closeModal()">×</button></div>${body}${buttons?`<div class="dialogfoot">${buttons}</div>`:''}`;labelControls(m);if(!m.open)m.showModal()}
function closeModal(){$('#modal').close()}
function act(fn){return Promise.resolve().then(fn).catch(e=>toast(e.message))}
async function go(p){if(current&&page==='editor'&&await saveCurrent(true)===false)return;page=p;filter='';category='';render()}
function render(){const labels={home:'总览',library:'原子能力库',services:'画板与服务',ideas:'创意探索',settings:'连接与设置',editor:current?.name||'服务设计'};$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">◈</div><span>glasshouse</span></div><div class="sub">BUILD WHAT'S NEXT</div><div class="navlabel">WORKSPACE</div>${[['home','◫','工作台',''],['library','◇','原子能力库',atoms().length],['services','⌘','画板与服务',services().length],['ideas','✳','创意探索',ideas().length]].map(([p,i,n,c])=>`<button class="nav ${page===p?'active':''}" onclick="go('${p}')"><span class="ico">${i}</span><span>${n}</span><span class="count">${c}</span></button>`).join('')}<div style="margin-top:28px" class="navlabel">PREFERENCES</div><button class="nav ${page==='settings'?'active':''}" onclick="go('settings')"><span class="ico">⚙</span><span>连接与设置</span></button><div class="sidebarfoot"><span class="dot"></span>本地工作空间<br><small>Display Glasses · v0.1<br>600 × 800 / 30° FOV</small></div></aside><main class="main"><header class="topbar"><div class="crumb">个人工作空间 <b>/ &nbsp;${esc(labels[page])}</b></div><div class="right"><span class="badge">LOCAL FIRST</span><button class="minibtn" onclick="exportAll()">↗ 导出工作空间</button><span class="brandmark" style="width:27px;height:27px;line-height:27px;font-size:11px;background:#dde7d4;color:#60764d">WY</span></div></header><div id="body"></div></main></div>`;({home:renderHome,library:renderLibrary,services:renderServices,ideas:renderIdeas,settings:renderSettings,editor:renderEditor}[page]||renderHome)()}
function serviceCard(s){return `<article class="card"><div class="row" style="justify-content:space-between"><div class="cardicon">${s.kind==='brainstorm'?'✳':'⌘'}</div><span class="badge ${s.kind==='brainstorm'?'orange':'blue'}">${s.kind==='brainstorm'?'创意画板':'服务设计'}</span></div><h3>${esc(s.name)}</h3><p>${esc(s.description||'从原子能力出发，构建新的服务可能。')}</p><div class="cardfoot"><small>${s.nodes?.length||0} 个能力 · v${s._revision||1}</small><div class="row"><button class="minibtn" onclick="openService('${s.id}')">打开 ↗</button><button class="minibtn" onclick="renameService('${s.id}')">⋯</button></div></div></article>`}
function renderHome(){$('#body').innerHTML=`<div class="content"><div class="pagehead"><div><div class="eyebrow">YOUR IDEAS, CONNECTED.</div><h1>让能力，生长出可能性。</h1><p class="subtitle">从一块积木到一个服务，在这里探索眼镜的下一种体验。</p></div><button class="primary" onclick="newService()">＋ 新建画板</button></div><div class="hero"><div><span class="badge">DISPLAY GLASSES PLAYGROUND</span><h2 style="margin-top:17px">选择能力，连接想象。<br>把一个念头变成可交互的体验。</h2><p>自由编排 · AI 共创 · 设备模拟</p><button class="soft" style="margin-top:19px" onclick="openCreateAI()">✳ 从一句话开始 &nbsp; ↗</button></div><div class="hero-art"><div class="block">⌁</div><div class="block">✳</div><div class="block">◫</div></div></div><div class="stats">${[[atoms().length,'原子能力','8 个能力领域'],[services().length,'服务画板','持续迭代你的设计'],[ideas().length,'创意方向','等待被探索的可能'],['600 × 800','眼镜显示区域','彩色光波导 · 30°']].map(x=>`<div class="stat"><strong>${x[0]}</strong>${x[1]}<small style="display:block;margin-top:6px">${x[2]}</small></div>`).join('')}</div><div class="sectionhead"><h2>继续你的探索</h2><button class="minibtn" onclick="go('services')">全部画板 ↗</button></div><div class="grid">${services().slice(0,3).map(serviceCard).join('')}</div><div class="sectionhead" style="margin-top:30px"><h2>从一个场景出发</h2><small>可以自由修改的起点</small></div><div class="grid">${[['calendar','▦','课表与日程','连接飞书日历，查看下一节课与当天安排。'],['weather','☼','天气与日历','天气、日期和农历，一眼获取今天的信息。'],['caption','≋','实时字幕与翻译','用模拟语段，探索字幕与翻译的呈现方式。']].map(x=>`<article class="card" onclick="createTemplate('${x[0]}')" style="cursor:pointer"><div class="cardicon">${x[1]}</div><h3>${x[2]}</h3><p>${x[3]}</p><div class="cardfoot"><span class="badge">场景模板</span><span>↗</span></div></article>`).join('')}</div></div>`}
function renderLibrary(){const list=atoms().filter(a=>(!category||a.category===category)&&(!filter||[a.name,a.description,a.id,...a.tags||[]].join(' ').toLowerCase().includes(filter.toLowerCase())));$('#body').innerHTML=`<div class="content"><div class="pagehead"><div><div class="eyebrow">THE ATOMIC LIBRARY</div><h1>每一种可能，从积木开始。</h1><p class="subtitle">能力定义与执行状态分开管理。候选定义不代表已经实现。</p></div><button class="primary" onclick="editAtom()">＋ 创建能力</button></div><div class="filters"><input placeholder="搜索名称、描述或标签…" value="${esc(filter)}" oninput="filter=this.value;renderLibrarySearch()" id="atomSearch"><button onclick="showTrash()">回收站</button><button onclick="bulkStatus()">批量设置状态</button></div><div class="category-tabs" role="tablist" aria-label="原子能力分类">${['',...categories()].map((c,i)=>`<button role="tab" aria-selected="${category===c}" tabindex="${category===c?0:-1}" data-category-index="${i}" onclick="selectAtomCategory(${i})" onkeydown="categoryTabKey(event,${i})">${esc(c||'全部')}<span>${atoms().filter(a=>!c||a.category===c).length}</span></button>`).join('')}</div><div id="atomResults" role="tabpanel" aria-label="能力列表"><div class="sectionhead"><small>${list.length} 个能力</small><span class="tagline">INPUT → PROCESS → EXPERIENCE</span></div><div class="grid">${list.map(atomCard).join('')}</div></div></div>`}
function atomCard(a){return `<article class="card"><div class="row" style="justify-content:space-between;margin-bottom:16px"><span class="badge" style="color:${esc(a.color)}"><span title="${esc(a.id)}">${esc(a.id.length>12?a.id.slice(0,8)+'…':a.id)}</span> · ${esc(a.category)}</span><label style="margin:0"><input type="checkbox" class="bulkcheck" value="${esc(a.id)}" style="width:auto"></label></div><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><div class="ports"><div><span class="portdot">○</span>${esc(a.input)}</div><div><span class="portdot">●</span>${esc(a.output)}</div></div><div class="cardfoot"><span class="badge">${esc(a.status)}</span><button class="minibtn" onclick="editAtom('${a.id}')">编辑 ↗</button></div></article>`}
function selectAtomCategory(i){category=['',...categories()][i];renderLibrary();$('[data-category-index="'+i+'"]').focus()}
function categoryTabKey(e,i){const n=categories().length+1;let next;if(e.key==='ArrowRight')next=(i+1)%n;else if(e.key==='ArrowLeft')next=(i+n-1)%n;else if(e.key==='Home')next=0;else if(e.key==='End')next=n-1;else return;e.preventDefault();selectAtomCategory(next)}
function renderLibrarySearch(){const list=atoms().filter(a=>(!category||a.category===category)&&[a.name,a.description,a.id,...a.tags||[]].join(' ').toLowerCase().includes(filter.toLowerCase()));$('#atomResults').innerHTML=`<small>${list.length} 个能力</small><div class="grid" style="margin-top:16px">${list.map(atomCard).join('')||'<div class="empty">没有匹配的能力，请更换分类或搜索词。</div>'}</div>`}
function editAtom(id){const a=atoms().find(a=>a.id===id)||{name:'',description:'',category:categories()[0],input:'',output:'',tags:[],example:'',status:'构想',constraints:''};modal(id?'编辑原子能力':'创建原子能力',`<label>能力名称</label><input id="aname" value="${esc(a.name)}"><label>能力描述</label><textarea id="adesc">${esc(a.description)}</textarea><div class="formgrid"><div><label>分类</label><select id="acat">${categories().map(c=>`<option ${a.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div><label>实现状态</label><select id="astatus">${['构想','待接入','可模拟','可执行','待建设','设备不支持'].map(s=>`<option ${s===a.status?'selected':''}>${s}</option>`).join('')}</select></div><div><label>输入</label><input id="ain" value="${esc(a.input)}"></div><div><label>输出</label><input id="aout" value="${esc(a.output)}"></div></div><label>标签（逗号分隔）</label><input id="atags" value="${esc((a.tags||[]).join(','))}"><label>示例</label><textarea id="aexample">${esc(a.example)}</textarea><label>约束 / 执行策略</label><textarea id="aconstraint">${esc(a.constraints)}</textarea>`,`${id?`<button class="danger" onclick="removeDoc('${id}')">移入回收站</button>`:''}<button class="primary" id="saveAtom">保存能力</button>`);$('#saveAtom').onclick=()=>act(async()=>{if(!$('#aname').value.trim())throw Error('请填写名称');await put({...a,id:a.id||uid(),name:$('#aname').value.trim(),description:$('#adesc').value,category:$('#acat').value,status:$('#astatus').value,input:$('#ain').value,output:$('#aout').value,tags:$('#atags').value.split(',').filter(Boolean),example:$('#aexample').value,constraints:$('#aconstraint').value},'atom');closeModal();render();toast('已保存；已有服务继续引用原版本')})}
async function removeDoc(id){await api('delete',{id});await refresh();closeModal();render();toast('已移入回收站，可恢复')}
function bulkStatus(){const ids=$$('.bulkcheck:checked').map(e=>e.value);if(!ids.length)return toast('先勾选需要批量修改的能力');modal('批量修改状态',`<p>已选择 ${ids.length} 个能力</p><label>实现状态</label><select id="bulkstatus">${['构想','待接入','可模拟','可执行','待建设','设备不支持'].map(x=>`<option>${x}</option>`).join('')}</select>`,`<button class="primary" id="dobulk">更新</button>`);$('#dobulk').onclick=()=>act(async()=>{for(const id of ids)await put({...atoms().find(a=>a.id===id),status:$('#bulkstatus').value},'atom');closeModal();render()})}
function showTrash(){const list=state.documents.filter(x=>x.deleted);modal('回收站',list.length?list.map(d=>`<div class="step row" style="justify-content:space-between">${esc(d.name||d.title||d.id)}<button onclick="restore('${d.id}')">恢复</button></div>`).join(''):'没有已删除内容')}
async function restore(id){const d=state.documents.find(x=>x.id===id);await put({...d,deleted:false},d._kind);closeModal();render()}
function renderServices(){$('#body').innerHTML=`<div class="content"><div class="pagehead"><div><div class="eyebrow">YOUR CANVASES</div><h1>画板与服务</h1><p class="subtitle">从探索到落地，每一版想法都有迹可循。</p></div><button class="primary" onclick="newService()">＋ 新建画板</button></div><div class="filters"><input placeholder="搜索画板…" oninput="filter=this.value;listServices()"><select onchange="searchMode=this.value;listServices()"><option value="all">全部画板</option><option value="service">服务设计</option><option value="brainstorm">创意画板</option></select><button onclick="showTrash()">回收站</button></div><div class="grid" id="serviceList"></div></div>`;listServices()}
function listServices(){$('#serviceList').innerHTML=services().filter(s=>(searchMode==='all'||s.kind===searchMode)&&(s.name+s.description).includes(filter)).map(serviceCard).join('')||'<div class="empty">还没有匹配的画板</div>'}
function newService(){modal('新建画板','<label>名称</label><input id="newname" placeholder="例如：我的课表助手"><label>画板类型</label><select id="newkind"><option value="service">服务设计</option><option value="brainstorm">创意探索</option></select>','<button class="primary" id="createService">创建画板</button>');if(page==='ideas')$('#newkind').value='brainstorm';$('#createService').onclick=()=>act(async()=>{const name=$('#newname').value.trim();if(!name)throw Error('请输入名称');const s=await put({id:uid(),name,kind:$('#newkind').value,description:'',nodes:[],edges:[],elements:baseElements('新的服务','从选择能力开始'),deviceVersion:'device-v1',steps:[],messages:[]},'service');closeModal();openService(s.id)})}
function baseElements(title,body){return [{id:uid(),type:'text',text:'LEGO / DISPLAY',x:32,y:32,w:536,h:40,fontSize:24,color:'#bdbdbd',background:'transparent',radius:0,action:'none'},{id:uid(),type:'text',text:title,x:32,y:110,w:410,h:100,fontSize:46,color:'#ffffff',background:'transparent',radius:0,action:'none'},{id:uid(),type:'card',text:body,x:32,y:250,w:536,h:200,fontSize:32,color:'#ffffff',background:'#292929',radius:32,action:'detail'},{id:uid(),type:'icon',icon:'cube',text:'',x:470,y:112,w:80,h:80,color:'#ff4f00',background:'transparent',radius:0,action:'none'}]}
async function createTemplate(type){const spec={calendar:{name:'课表与日程',desc:'把下一节课，放在视线之内。',ids:['I07','C02','F02','O07','O08','O09'],body:'09:00  交互设计基础\n设计楼 A301\n点击查看课程详情'},weather:{name:'天气与日历',desc:'一眼掌握天气与今天的安排。',ids:['C04','F02','O07','O08'],body:'尚未获取天气\n请选择位置并实时读取'},caption:{name:'实时字幕与翻译',desc:'模拟流式语段与双语字幕的呈现。',ids:['I02','P01','P07','O08'],body:'等待模拟语段…'}}[type];const nodes=spec.ids.map((id,i)=>({id:uid(),atomId:id,snapshot:structuredClone(atoms().find(a=>a.id===id)),x:70+i%3*285,y:90+Math.floor(i/3)*210,mode:'required',config:''}));const elements=baseElements(spec.name,spec.body);if(type==='weather')elements.push({id:uid(),type:'text',text:'日期与农历',binding:'date',x:32,y:520,w:536,h:180,fontSize:30,color:'#c7e2a9',background:'transparent',radius:0,action:'none'});elements[2].binding=type==='caption'?'caption':type;const s=await put({id:uid(),name:services().some(s=>s.name===spec.name)?spec.name+' · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):spec.name,description:spec.desc,kind:'service',template:type,nodes,edges:nodes.slice(1).map((n,i)=>({from:n.atomId.startsWith('O')?nodes.find(x=>x.atomId==='F02'||x.atomId==='P07').id:nodes[i].id,to:n.id,mapping:'待定义'})),elements,deviceVersion:'device-v1',steps:[],messages:[]},'service');openService(s.id)}
function openService(id){captureAIDraft();current=structuredClone(services().find(s=>s.id===id));if(!current)return;page='editor';view='canvas';selected=null;undo=[];redo=[];detail=false;aiDraft=current.aiDraft||'';simData=current.dataSnapshot?.items||current.dataSnapshot?.data||(current.template==='calendar'?sampleEvents():null);simSource=current.dataSnapshot?'缓存 · '+current.dataSnapshot.source:'模拟数据';render()}
function checkpoint(){undo.push(JSON.stringify(current));if(undo.length>60)undo.shift();redo=[]}
function undoChange(){if(!undo.length)return;redo.push(JSON.stringify(current));current={...JSON.parse(undo.pop()),_revision:current._revision};clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveCurrent(true),1800);renderEditor()}
function redoChange(){if(!redo.length)return;undo.push(JSON.stringify(current));current={...JSON.parse(redo.pop()),_revision:current._revision};clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveCurrent(true),1800);renderEditor()}
async function saveCurrent(quiet=false){if(!current)return;try{current=await put(current,'service');if(!quiet)toast('已保存新版本')}catch(e){toast(e.message)}}
function renameService(id){const s=services().find(x=>x.id===id);modal('画板管理',`<label>名称</label><input id="rename" value="${esc(s.name)}"><label>描述</label><textarea id="redesc">${esc(s.description)}</textarea>`,`<button class="danger" onclick="removeDoc('${id}')">移入回收站</button><button class="primary" id="renamesave">保存</button>`);$('#renamesave').onclick=()=>act(async()=>{await put({...s,name:$('#rename').value,description:$('#redesc').value},'service');closeModal();render()})}
function renderEditor(){if(!current)return;$('#body').innerHTML=`<div class="worktoolbar"><div class="row"><button class="minibtn" onclick="go('services')">←</button><b>${esc(current.name)}</b><span class="badge">v${current._revision||1}</span></div><div class="row"><button class="minibtn" onclick="undoChange()">↶</button><button class="minibtn" onclick="redoChange()">↷</button><button class="minibtn" onclick="history()">历史</button><button class="minibtn" onclick="validateDesign()">检查设计</button><button class="soft minibtn" onclick="runSimulation()">▷ 模拟流程</button><button class="primary minibtn" onclick="saveCurrent()">保存版本</button></div></div><div class="workspace"><aside class="panel left" id="leftpanel"></aside><section class="stage" id="stage"><div class="stagebar">${[['tower','组装塔'],['canvas','流程画布'],['design','界面设计'],['simulate','运行预览']].map(([v,n])=>`<button class="${view===v?'soft':''} minibtn" onclick="view='${v}';selected=null;renderEditor()">${n}</button>`).join('')}</div><div id="stagecontent"></div></section><aside class="panel rightpanel" id="rightpanel"></aside></div>`;renderLeft();renderStage();renderRight()}
function renderLeft(){const design=['design','simulate'].includes(view);$('#leftpanel').innerHTML=design?`<div class="sectionhead"><h3>图层</h3><button class="minibtn" onclick="addElement()">＋</button></div>${current.elements.map((e,i)=>`<div role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}" class="item ${selected===e.id?'selected':''}" onclick="selected='${e.id}';renderLeft();renderStage();renderRight()">${e.locked?'▣':'▤'} ${esc((e.text||'图层').slice(0,18))}<small>${e.type} · ${e.binding||'静态内容'}</small></div>`).join('')}<div class="notice">${view==='design'?'拖动位置、右下角调整尺寸。属性以 600×800 设计像素保存。':'方向键导航 · Enter 确认 · Escape 返回。点击模拟器外再操作。'}</div><button style="width:100%;margin-top:12px" onclick="exportDemo()">↗ 导出 HTML Demo</button>`:`<h3>能力积木 <small>${atoms().length}</small></h3><input placeholder="搜索能力…" id="paletteSearch" oninput="renderPalette(this.value)"><div id="palette" style="margin-top:15px"></div>`;if(!design)renderPalette('')}
function renderPalette(q){$('#palette').innerHTML=atoms().filter(a=>[a.name,a.id,a.category].join(' ').includes(q)).map(a=>`<div role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click()}" class="item" onclick="addNode('${a.id}')"><span class="tiny" style="color:${a.color}">${a.id}</span> ${esc(a.name)}<small>${esc(a.category)}</small></div>`).join('')}
function addNode(id){checkpoint();const a=atoms().find(a=>a.id===id);current.nodes.push({id:uid(),atomId:id,snapshot:structuredClone(a),x:70+current.nodes.length%3*285,y:90+Math.floor(current.nodes.length/3)*210,mode:'required',config:''});renderStage();renderRight();toast('已添加能力实例，引用当前版本')}
function renderStage(){const el=$('#stagecontent');if(!el)return;if(view==='canvas'){el.innerHTML=`<div class="nodearea"><svg class="svgwires" width="1400" height="1000">${current.edges.map(e=>{const a=current.nodes.find(n=>n.id===e.from),b=current.nodes.find(n=>n.id===e.to);if(!a||!b)return '';const x=a.x+210,y=a.y+60;return `<path d="M${x},${y} C${x+80},${y} ${b.x-80},${b.y+60} ${b.x},${b.y+60}" fill="none" stroke="#9fb38f" stroke-width="2"/>`}).join('')}</svg>${current.nodes.map(n=>`<div class="node ${selected===n.id?'selected':''}" data-node="${n.id}" style="left:${n.x}px;top:${n.y}px"><span class="port in" data-port-in="${n.id}" title="连接到这里"></span><div class="nodehead"><span class="badge">${esc(n.atomId)}</span><b>${esc(n.snapshot.name)}</b></div><small>${esc(n.snapshot.input)}</small><small>↓ ${esc(n.snapshot.output)}</small><div style="margin-top:10px"><span class="badge ${n.mode==='optional'?'orange':''}">${n.mode==='optional'?'备选':'必选'}</span> <small style="display:inline">v${n.snapshot._revision||1}</small></div><span class="port out" data-port-out="${n.id}" title="从此连接"></span></div>`).join('')}${!current.nodes.length?'<div class="empty" style="width:600px;padding-top:140px">从左侧选择一个能力，开始编排<br><br>点击节点右侧端口，再点另一个节点左侧端口连接</div>':''}</div>`;bindNodeDrag();return}if(view==='tower'){el.innerHTML=`<div class="tower">${categories().map(c=>`<div class="tier"><h3>${esc(c)}</h3><div class="tierchips">${atoms().filter(a=>a.category===c).map(a=>`<button class="${current.nodes.some(n=>n.atomId===a.id)?'chosen':''} minibtn" onclick="toggleAtom('${a.id}')">${current.nodes.some(n=>n.atomId===a.id)?'✓ ':''}${esc(a.name)}</button>`).join('')}</div></div>`).join('')}</div>`;return}renderPreview()}
function bindNodeDrag(){$$('[data-port-out]').forEach(e=>e.onclick=ev=>{ev.stopPropagation();linkFrom=e.dataset.portOut;toast('选择目标节点左侧端口')});$$('[data-port-in]').forEach(e=>e.onclick=ev=>{ev.stopPropagation();if(linkFrom&&linkFrom!==e.dataset.portIn){checkpoint();current.edges.push({from:linkFrom,to:e.dataset.portIn,mapping:'待定义'});linkFrom=null;renderStage()}});$$('[data-node]').forEach(el=>{el.onpointerdown=ev=>{if(ev.target.classList.contains('port'))return;selected=el.dataset.node;renderRight();const n=current.nodes.find(n=>n.id===selected),sx=ev.clientX,sy=ev.clientY,x=n.x,y=n.y;checkpoint();el.setPointerCapture(ev.pointerId);el.onpointermove=e=>{n.x=Math.max(0,Math.round((x+e.clientX-sx)/8)*8);n.y=Math.max(0,Math.round((y+e.clientY-sy)/8)*8);el.style.left=n.x+'px';el.style.top=n.y+'px'};el.onpointerup=()=>{el.onpointermove=null;renderStage()}}})}
function toggleAtom(id){const n=current.nodes.find(n=>n.atomId===id);if(n){checkpoint();current.nodes=current.nodes.filter(x=>x.atomId!==id);current.edges=current.edges.filter(e=>e.from!==n.id&&e.to!==n.id);renderStage()}else addNode(id)}
function renderRight(){const priorPrompt=$('#aiprompt')?.value||'', priorText=$('#simtext')?.value||'';let html='';if(view==='canvas'||view==='tower'){const n=current.nodes.find(n=>n.id===selected);html=n?`<h3>${esc(n.snapshot.name)}</h3><span class="badge">引用 v${n.snapshot._revision||1}</span><label>选择方式</label><select onchange="updateNode('mode',this.value)"><option value="required" ${n.mode==='required'?'selected':''}>必选</option><option value="optional" ${n.mode==='optional'?'selected':''}>备选</option></select><label>执行策略 / 参数 / 失败处理</label><textarea onchange="updateNode('config',this.value)">${esc(n.config)}</textarea><label>输入 → 输出</label><div class="notice">${esc(n.snapshot.input)} → ${esc(n.snapshot.output)}</div><label>能力边界</label><div class="hint">${esc(n.snapshot.constraints)}</div><button style="margin-top:12px" onclick="upgradeNode()">检查 / 升级能力引用</button><button class="danger" style="margin-top:8px" onclick="deleteNode()">移除实例</button><label>输出连线</label>${current.edges.filter(e=>e.from===n.id).map(e=>`<div class="step"><small>→ ${esc(current.nodes.find(x=>x.id===e.to)?.snapshot.name)}</small><input placeholder="字段映射 / 条件" value="${esc(e.mapping)}" onchange="updateEdge('${e.to}',this.value)"><button class="minibtn danger" onclick="deleteEdge('${e.to}')">断开</button></div>`).join('')}`:`<h3>服务概览</h3><div class="notice">${current.nodes.length} 个能力 · ${current.edges.length} 条连接<br>每层可多选，也可以留空。</div><label>服务描述</label><textarea oninput="checkpoint();current.description=this.value">${esc(current.description)}</textarea><div class="hint">点击节点查看属性。连接后请定义字段映射与执行策略；连线本身不代表可执行。</div>`}else if(view==='design'){const e=current.elements.find(e=>e.id===selected);html=e?`<h3>图层属性</h3><label>文本</label><textarea oninput="updateElement('text',this.value)">${esc(e.text)}</textarea><div class="formgrid">${[['x','X'],['y','Y'],['w','宽度'],['h','高度'],['fontSize','字号'],['radius','圆角']].map(([k,n])=>`<div><label>${n}</label><input type="number" value="${e[k]||0}" onchange="updateElement('${k}',Number(this.value))"></div>`).join('')}</div><label>文字颜色</label><input type="color" value="${e.color||'#ffffff'}" onchange="updateElement('color',this.value)"><label>背景（CSS 颜色）</label><input value="${esc(e.background)}" onchange="updateElement('background',this.value)"><label>数据绑定</label><select onchange="updateElement('binding',this.value)">${['','calendar','weather','caption','date','camera'].map(x=>`<option ${e.binding===x?'selected':''} value="${x}">${x||'静态内容'}</option>`).join('')}</select><label>确认动作</label><select onchange="updateElement('action',this.value)">${['none','detail','back','next'].map(x=>`<option ${e.action===x?'selected':''}>${x}</option>`).join('')}</select><label class="checkrow"><input type="checkbox" ${e.locked?'checked':''} onchange="updateElement('locked',this.checked)">锁定图层 / 防止 AI 覆盖</label><div class="row"><button class="minibtn" onclick="duplicateElement()">复制</button><button class="minibtn" onclick="alignElement()">水平居中</button><button class="minibtn danger" onclick="deleteElement()">删除</button></div>`:'<h3>设计属性</h3><div class="notice">选中图层以编辑位置、字体、颜色、数据与交互。<br>底部 ＋ 可添加新图层。</div>'}else{html=`<h3>模拟控制台</h3><span class="badge">${esc(simSource)}</span><label>静态背景</label><select onchange="background=this.value;renderPreview()">${[['dark','昏暗'],['bright','明亮'],['busy','复杂']].map(([v,n])=>`<option value="${v}" ${background===v?'selected':''}>${n}</option>`).join('')}</select><label>输入设备</label><select id="inputDevice" onchange="inputDeviceChoice=this.value"><option>OFN</option><option>滚轴</option><option>手势外设</option><option>HID</option></select><div class="device-controls"><button onclick="simEvent('prev')">↑</button><button onclick="simEvent('confirm')">确认</button><button onclick="simEvent('next')">↓</button><button onclick="simEvent('back')">返回</button></div><button style="width:100%;margin-top:9px" onclick="editInputMapping()">配置输入映射</button><label>ASR 文字模拟 / 字幕语段</label><textarea id="simtext" placeholder="今天的课程即将开始。请前往 A301 教室。"></textarea><button style="margin-top:8px;width:100%" onclick="streamCaption()">≋ 模拟流式字幕</button><button style="margin-top:8px;width:100%" onclick="translateSimulation()">模拟双语字幕</button><button style="margin-top:8px;width:100%" onclick="simulateTTS()">◖ 模拟喇叭 + 字幕</button><label>Camera 样例图</label><input type="file" accept="image/*" onchange="cameraSample(this)"><label>姿态（仅事件模拟）</label><input type="range" min="-90" max="90" value="0" oninput="poseEvent(Number(this.value))"><small id="poseValue">0°</small><button style="width:100%;margin-top:10px" onclick="editMockData()">编辑模拟课程 / 数据</button><label>真实数据</label><button style="width:100%" onclick="calendarDialog()">读取飞书测试日历</button><button style="width:100%;margin-top:8px" onclick="weatherDialog()">读取天气</button><div class="hint" id="simlog">等待输入事件…</div>`}$('#rightpanel').innerHTML=html+`<div class="chatbox"><h3>✳ AI 共创</h3><textarea id="aiprompt" placeholder="描述你想创建或修改的体验…"></textarea><label class="checkrow"><input id="research" type="checkbox">联网研究（Tavily）</label><button class="primary" onclick="requestAI('design')">生成设计建议 ↗</button><button onclick="requestAI('brainstorm')">探索更多可能</button><small style="display:block;margin-top:9px">${esc(prefs.provider)} · ${esc(prefs.model||'请先配置模型')}</small></div>`;if($('#aiprompt'))$('#aiprompt').value=priorPrompt;if($('#simtext'))$('#simtext').value=priorText;if($('#inputDevice'))$('#inputDevice').value=inputDeviceChoice}
function updateNode(k,v){checkpoint();current.nodes.find(n=>n.id===selected)[k]=v;if(k==='mode')renderStage()}
function updateEdge(to,v){checkpoint();current.edges.find(e=>e.from===selected&&e.to===to).mapping=v}
function deleteEdge(to){checkpoint();current.edges=current.edges.filter(e=>!(e.from===selected&&e.to===to));renderStage();renderRight()}
function deleteNode(){checkpoint();current.nodes=current.nodes.filter(n=>n.id!==selected);current.edges=current.edges.filter(e=>e.from!==selected&&e.to!==selected);selected=null;renderStage();renderRight()}
function upgradeNode(){const n=current.nodes.find(x=>x.id===selected),a=atoms().find(a=>a.id===n.atomId);if(!a)return toast('原能力已删除；当前快照仍可使用');modal('能力版本对比',`<p>当前 v${n.snapshot._revision||1} → 能力库 v${a._revision}</p><div class="split"><div class="log">${esc(JSON.stringify(n.snapshot,null,2))}</div><div class="log">${esc(JSON.stringify(a,null,2))}</div></div>`,`<button class="primary" id="upgrade">更新此实例</button>`);$('#upgrade').onclick=()=>{checkpoint();n.snapshot=structuredClone(a);closeModal();renderEditor()}}
function updateElement(k,v){const e=current.elements.find(e=>e.id===selected);if(e.locked&&k!=='locked')return toast('请先解锁图层');checkpoint();e[k]=v;renderPreview()}
function addElement(){checkpoint();const e={id:uid(),type:'text',text:'新的内容',x:32,y:480,w:536,h:96,fontSize:32,color:'#ffffff',background:'transparent',radius:0,action:'none'};current.elements.push(e);selected=e.id;renderEditor()}
function duplicateElement(){const e=current.elements.find(e=>e.id===selected);checkpoint();const copy={...e,id:uid(),x:e.x+8,y:e.y+16,locked:false};current.elements.push(copy);selected=copy.id;renderEditor()}
function alignElement(){const e=current.elements.find(e=>e.id===selected);updateElement('x',Math.round((600-e.w)/2));renderRight()}
function deleteElement(){const e=current.elements.find(e=>e.id===selected);if(e?.locked)return toast('请先解锁图层');checkpoint();current.elements=current.elements.filter(e=>e.id!==selected);selected=null;renderEditor()}
function boundText(e){const savedSim=simData;if(e.binding==='weather'&&current.dataSnapshots?.weather)simData=current.dataSnapshots.weather.data;if(e.binding==='calendar'&&current.dataSnapshots?.calendar)simData=current.dataSnapshots.calendar.items;try{return boundTextValue(e)}finally{simData=savedSim}}
function boundTextValue(e){if(view!=='simulate')return e.text;if(e.binding==='camera')return current.cameraResult||'尚未提供模拟识别结果';if(e.binding==='date')return new Date().toLocaleDateString('zh-CN',{weekday:'long',year:'numeric',month:'long',day:'numeric'})+'\n'+new Intl.DateTimeFormat('zh-CN-u-ca-chinese',{dateStyle:'full'}).format(new Date());if(e.binding==='weather'&&simData?.current)return `${simData.current.temperature_2m}°\n湿度 ${simData.current.relative_humidity_2m}%\n${simData.current.time}`;if(e.binding==='calendar'&&Array.isArray(simData)){if(!simData.length)return '这段时间没有日程';const x=simData[focusIndex%simData.length];return detail?`${x.title}\n${x.time}\n${x.location||''}\n${x.description||'暂无详细描述'}`:`${x.time}\n${x.title}\n${x.location||''}`;}if(e.binding==='caption'&&typeof simData==='string')return simData;return e.text}
function safeColor(c,fallback){return CSS.supports('color',c)?c:fallback}
function renderPreview(){const el=$('#stagecontent');if(!el)return;const interactive=current.elements.filter(e=>e.action&&e.action!=='none');el.innerHTML=`<div class="previewwrap"><div class="device-frame"><div class="device-meta"><span>DISPLAY GLASSES</span><span>600 × 800 · 30°</span></div><div class="screenclip"><div class="screen ${background}" id="screen">${current.elements.map(e=>`<div class="element ${selected===e.id&&view==='design'?'editing':''} ${e.locked?'locked':''} ${view==='simulate'&&interactive[focusIndex%Math.max(1,interactive.length)]?.id===e.id?'focused':''}" data-el="${e.id}" style="left:${Number(e.x)||0}px;top:${Number(e.y)||0}px;width:${Number(e.w)||100}px;height:${Number(e.h)||100}px;font-size:${Number(e.fontSize)||32}px;color:${safeColor(e.color,'white')};background:${safeColor(e.background,'transparent')};border-radius:${Number(e.radius)||0}px;padding:${e.type==='card'?24:0}px">${esc(boundText(e))}${view==='design'&&!e.locked?'<span class="handle"></span>':''}</div>`).join('')}</div></div><div class="device-controls"><button onclick="simEvent('prev')">◁</button><button onclick="simEvent('confirm')">●</button><button onclick="simEvent('next')">▷</button><button onclick="simEvent('back')">↩</button></div></div></div><div style="text-align:center;color:#8c9884;font-size:10px;margin-bottom:20px">${view==='design'?'设计模式 · 50% 比例 · 8px 吸附':'静态背景模拟 · 不代表真实光学效果'}</div>`;$$('[data-el]').forEach(el=>{el.onpointerdown=ev=>{if(view!=='design'){simEvent('confirm');return}selected=el.dataset.el;renderLeft();renderRight();const e=current.elements.find(e=>e.id===selected);if(e.locked){renderPreview();return}checkpoint();const resize=ev.target.classList.contains('handle'),sx=ev.clientX,sy=ev.clientY,base={...e};el.setPointerCapture(ev.pointerId);el.onpointermove=evt=>{const dx=(evt.clientX-sx)*2,dy=(evt.clientY-sy)*2;if(resize){e.w=Math.max(32,Math.round((base.w+dx)/8)*8);e.h=Math.max(32,Math.round((base.h+dy)/8)*8);el.style.width=e.w+'px';el.style.height=e.h+'px'}else{e.x=Math.max(0,Math.round((base.x+dx)/8)*8);e.y=Math.max(0,Math.round((base.y+dy)/8)*8);el.style.left=e.x+'px';el.style.top=e.y+'px'}};el.onpointerup=()=>{el.onpointermove=null;renderPreview();renderRight()}}})}
function simEvent(action){if(view!=='simulate'){view='simulate';renderEditor()}const count=Array.isArray(simData)?simData.length:current.elements.filter(e=>e.action&&e.action!=='none').length;if(action==='next')focusIndex=(focusIndex+1)%Math.max(1,count);if(action==='prev')focusIndex=(focusIndex-1+Math.max(1,count))%Math.max(1,count);if(action==='back')detail=false;if(action==='confirm'){const elements=current.elements.filter(e=>e.action&&e.action!=='none'),e=elements[focusIndex%Math.max(1,elements.length)];if(e?.action==='back')detail=false;else if(e?.action==='next')focusIndex++;else detail=!detail}renderPreview();if($('#simlog'))$('#simlog').textContent=`${new Date().toLocaleTimeString()} · ${$('#inputDevice')?.value||'OFN'} → ${action} · ${detail?'详情':'概览'}`}
function streamCaption(){const text=$('#simtext').value||'今天的课程即将开始。请前往 A301 教室。';if(!current.elements.some(e=>e.binding==='caption')){checkpoint();current.elements.push({...baseElements('','')[2],id:uid(),text:'',binding:'caption',y:490,h:230})}clearInterval(streamTimer);simSource='模拟流式字幕（非真实 ASR / 翻译）';let i=0;streamTimer=setInterval(()=>{simData=text.slice(0,++i);renderPreview();if(i>=text.length)clearInterval(streamTimer)},85);renderRight()}
function simulateTTS(){const text=$('#simtext').value||'下一节课是交互设计基础，请前往 A301 教室。';toast('◖ 喇叭播放状态模拟 · 无真实语音合成');if(!current.elements.some(e=>e.binding==='caption')){checkpoint();current.elements.push({...baseElements('','')[2],id:uid(),binding:'caption',y:500,h:240})}simData='◖  播报中\n'+text;simSource='模拟 TTS 状态与字幕';renderPreview();renderRight();setTimeout(()=>{if(view==='simulate'){simData='◖  播报结束\n'+text;renderPreview()}},4000)}
function cameraSample(input){const file=input.files[0];if(!file)return;if(file.size>3e6)return toast('请使用3MB以内样例图');const reader=new FileReader();reader.onload=()=>{checkpoint();current.cameraSample=reader.result;modal('Camera 模拟样例',`<img src="${reader.result}" style="max-width:100%;max-height:300px"><label>预设识别结果（非真实视觉识别）</label><textarea id="cameraResult">${esc(current.cameraResult||'')}</textarea>`,`<button class="primary" id="saveCamera">保存样例</button>`);$('#saveCamera').onclick=()=>{current.cameraResult=$('#cameraResult').value;if(!current.elements.some(e=>e.binding==='camera'))current.elements.push({...baseElements('','')[2],id:uid(),binding:'camera',y:500,h:230});closeModal();renderPreview();toast('图像与预设结果将随服务保存和迁移')}};reader.readAsDataURL(file)}
function validateDesign(){const issues=[];if(!current.nodes.length)issues.push('尚未选择原子能力');current.nodes.forEach(n=>{if(!n.config)issues.push(n.snapshot.name+'：执行策略待定义');if(['O04','O05','I06'].includes(n.atomId))issues.push(n.snapshot.name+'：当前设备未确认支持 / 需适配');if(n.snapshot.status!=='可执行')issues.push(n.snapshot.name+'：当前是 '+n.snapshot.status)});current.edges.forEach(e=>{const a=current.nodes.find(n=>n.id===e.from),b=current.nodes.find(n=>n.id===e.to);if(!a||!b)issues.push('存在失效连线');else if(a.snapshot.output!==b.snapshot.input&&(!e.mapping||e.mapping==='待定义'))issues.push(a.snapshot.name+' → '+b.snapshot.name+'：需要显式字段适配')});current.elements.forEach(e=>{if(e.x<32||e.y<32||e.x+e.w>568||e.y+e.h>768)issues.push('图层“'+e.text.slice(0,12)+'”超出32px安全区');if(e.fontSize<26)issues.push('图层“'+e.text.slice(0,12)+'”字号小于建议值')});modal('设计检查',`<div class="notice">这是设计约束检查，不代表通用工作流已通过真实执行验证。</div>${issues.length?issues.map(x=>`<div class="step">${esc(x)}</div>`).join(''):'<p style="margin-top:20px">当前检查未发现问题。</p>'}`)}
async function history(){const list=await api('history?id='+encodeURIComponent(current.id));modal('版本历史',list.length?list.map(r=>`<div class="step row" style="justify-content:space-between"><span>v${r.revision} · ${new Date(r.updated*1000).toLocaleString()}</span><button onclick="restoreVersion(${r.revision})">恢复为新版本</button></div>`).join(''):'保存下一版本后，旧版本会出现在这里。')}
async function restoreVersion(rev){const rows=await api('history?id='+encodeURIComponent(current.id));const r=rows.find(r=>r.revision===rev);checkpoint();current={...JSON.parse(r.body),_revision:current._revision};await saveCurrent();closeModal();renderEditor()}
function openCreateAI(){modal('从一句话开始','<p>描述目标人群、使用场景和想要的体验。AI 会生成可编辑设计。</p><label>你的想法</label><textarea id="initialPrompt" placeholder="我想做一个查看今日课程的眼镜服务，可以滚动浏览并查看详情。"></textarea>','<button class="primary" id="startIdea">创建并生成设计</button>');$('#startIdea').onclick=()=>act(async()=>{const prompt=$('#initialPrompt').value.trim();if(!prompt)throw Error('请描述想法');const s=await put({id:uid(),name:'新的服务探索',kind:'service',description:prompt,nodes:[],edges:[],elements:baseElements('新的服务','等待 AI 设计'),messages:[]},'service');closeModal();aiOpen=true;openService(s.id);$('#aiprompt').value=prompt;await requestAI('design')})}
async function requestAI(mode){const prompt=$('#aiprompt')?.value.trim();if(!prompt)return toast('先描述希望创建或修改的体验');const research=$('#research')?.checked;const buttons=$$('.chatbox button');buttons.forEach(b=>b.disabled=true);toast(research?'正在检索资料并生成建议…':'正在生成设计建议…');try{const r=await api('ai',{provider:prefs.provider,model:prefs.model,mode,prompt,research,capabilities:atoms().map(a=>({id:a.id,name:a.name,input:a.input,output:a.output,status:a.status,scope:a.scope,selectable:a.selectable})),design:{name:current.name,nodes:current.nodes,elements:current.elements,description:current.description}});if(mode==='brainstorm'){if(!Array.isArray(r.result.ideas))throw Error('结果缺少创意列表');for(const idea of r.result.ideas)await put({...idea,id:uid(),serviceId:current.id,sources:r.sources,source:r.source,provider:r.provider,model:r.model},'idea');toast('已保存 '+r.result.ideas.length+' 个创意方向');go('ideas')}else previewSuggestion(r)}catch(e){toast(e.message)}finally{buttons.forEach(b=>b.disabled=false)}}
function previewSuggestion(run){const r=run.result;modal('AI 设计建议 · 应用前审阅',`<span class="badge">${esc(run.provider)} / ${esc(run.model)}</span><h3 style="margin:16px 0">${esc(r.title||'设计建议')}</h3><p>${esc(r.description||'')}</p><div class="split" style="margin-top:15px"><div class="notice">当前：${current.nodes.length} 个能力<br>${current.elements.length} 个图层<br>${current.elements.filter(e=>e.locked).length} 个锁定图层</div><div class="notice">建议：${r.selected?.length||0} 个能力<br>${r.elements?.length||0} 个图层<br>锁定图层将保留</div></div>${(r.steps||[]).map(s=>`<div class="step"><b>${esc(s.title)}</b><p>${esc(s.detail)}</p></div>`).join('')}<div class="hint">${esc((r.notes||[]).join('\n'))}</div><details><summary>查看完整建议</summary><pre class="log">${esc(JSON.stringify(r,null,2))}</pre></details>`,`<button onclick="closeModal()">保留当前设计</button><button class="primary" id="applyAI">应用建议</button>`);$('#applyAI').onclick=()=>{checkpoint();current.description=r.description||current.description;current.name=r.title||current.name;current.steps=r.steps||[];if(Array.isArray(r.selected)){const existing=current.nodes;current.nodes=r.selected.filter(id=>atoms().some(a=>a.id===id)).map((id,i)=>existing.find(n=>n.atomId===id)||{id:uid(),atomId:id,snapshot:structuredClone(atoms().find(a=>a.id===id)),x:70+i%3*285,y:90+Math.floor(i/3)*210,mode:'required',config:''});current.edges=current.edges.filter(e=>current.nodes.some(n=>n.id===e.from)&&current.nodes.some(n=>n.id===e.to))}if(Array.isArray(r.elements)){const locked=current.elements.filter(e=>e.locked);current.elements=[...r.elements.filter(e=>e&&typeof e.text==='string'&&!locked.some(l=>l.id===e.id)).map(e=>({...e,id:uid(),type:e.type==='card'?'card':'text',x:Number(e.x)||32,y:Number(e.y)||32,w:Math.max(32,Number(e.w)||536),h:Math.max(32,Number(e.h)||100),fontSize:Number(e.fontSize)||32,color:safeColor(e.color,'#ffffff'),background:safeColor(e.background,'transparent')})),...locked]}current.messages=current.messages||[];current.messages.push({runId:run.id,at:run.at});closeModal();view='design';selected=null;renderEditor();toast('已应用建议，可撤销；请检查布局和能力连接')}}
function renderIdeas(){$('#body').innerHTML=`<div class="content"><div class="pagehead"><div><div class="eyebrow">THE POSSIBILITY SPACE</div><h1>想象，还可以走得更远。</h1><p class="subtitle">从已有能力出发，发现不同人群、场景与服务形态。</p></div><button class="primary" onclick="newService()">＋ 新建探索画板</button></div><div class="notice" style="margin-bottom:22px">评分是模型的设计判断，不是市场验证。联网结果显示引用来源；待建设能力须遵守设备边界。</div><div class="filters"><input placeholder="搜索创意、人群或场景…" oninput="filter=this.value;listIdeas()"><select onchange="category=this.value;listIdeas()"><option value="">全部来源</option><option>模型推演</option><option>联网研究</option></select></div><div class="grid" id="ideaList"></div></div>`;listIdeas()}
function listIdeas(){$('#ideaList').innerHTML=ideas().filter(i=>(!category||i.source===category)&&JSON.stringify(i).includes(filter)).map(i=>`<article class="card"><div class="sectionhead"><span class="badge orange">${esc(i.source)}</span><span>✳</span></div><h3>${esc(i.title)}</h3><p>${esc(i.description||i.scenario)}</p><label>服务人群</label><p>${esc(i.audience)}</p><div class="score">${[['completeness','完整度'],['readiness','就绪度'],['potential','潜力假设']].map(([k,n])=>`<div><strong>${Number(i.scores?.[k])||0}</strong>${n}</div>`).join('')}</div><p>${esc(i.rationale)}</p><label>待建设 / 待验证</label><p>${esc([...(i.missing||[]),...(i.assumptions||[])].join(' · '))}</p>${(i.sources||[]).map(s=>`<a class="sourcelink" href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">↗ ${esc(s.title)}</a>`).join('')}<div class="cardfoot"><button class="minibtn" onclick="ideaToService('${i.id}')">转为服务画板 ↗</button><button class="minibtn danger" onclick="removeDoc('${i.id}')">删除</button></div></article>`).join('')||(filter||category?'<div class="empty">没有匹配的创意，请清除搜索或更换来源。</div>':'<div class="empty">在画板右侧输入想法，点击「探索更多可能」。<br>配置模型后，将在这里汇总真实生成的创意。</div>')}
function safeUrl(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
async function ideaToService(id){const i=ideas().find(x=>x.id===id),base=services().find(s=>s.id===i.serviceId);const s=await put({...structuredClone(base||{}),id:uid(),_revision:undefined,name:i.title,description:i.description||i.scenario,kind:'service',nodes:base?.nodes||[],edges:base?.edges||[],elements:base?.elements||baseElements(i.title,i.description||''),ideaId:id},'service');openService(s.id)}
function renderSettings(){$('#body').innerHTML=`<div class="content"><div class="pagehead"><div><div class="eyebrow">WORKSPACE SETTINGS</div><h1>连接你的能力世界。</h1><p class="subtitle">密钥仅保存在当前后台进程内，重启后需重新输入；不会进入迁移包。</p></div></div><div class="settingsgrid"><section class="card"><h2>模型供应商</h2><label>供应商</label><select id="provider" onchange="prefs.provider=this.value;savePrefs()">${['Gemini','Kimi','DeepSeek','OpenRouter'].map(x=>`<option ${prefs.provider===x?'selected':''}>${x}</option>`).join('')}</select><label>实际模型 ID</label><input id="model" value="${esc(prefs.model)}" placeholder="填写你的账号可调用的模型 ID"><label>API Key</label><input type="password" id="apiKey" autocomplete="off" placeholder="仅保存在后台内存"><button class="primary" style="margin-top:15px" onclick="saveProvider()">保存连接</button><p class="hint">官方接口直连；OpenRouter 为可选聚合入口。不会自动切换供应商发送内容。</p></section><section class="card"><h2>联网研究</h2><p>通过 Tavily 检索资料，将来源与摘要交给所选模型。未配置时会明确提示，不会伪装联网。</p><label>Tavily API Key</label><input type="password" id="searchKey" autocomplete="off"><button style="margin-top:15px" onclick="saveSearchKey()">保存检索密钥</button><div class="notice" style="margin-top:20px">已配置（当前进程）：${esc(state.keys.join('、')||'暂无')}<br>环境变量密钥不会显示在这里。</div></section><section class="card"><h2>数据连接器</h2><p>飞书 CLI：只读日历。天气：Open-Meteo。请在画板的运行预览中读取并绑定到界面。</p><div class="row" style="margin-top:20px"><button onclick="calendarDialog()">测试飞书连接</button><button onclick="weatherDialog()">测试天气连接</button></div><div class="hint">飞书使用本机已登录的 lark-cli。当前未配置任意命令执行或日程写入。</div></section><section class="card"><h2>数据与迁移</h2><p>包含能力、画板、内嵌样例图、版本、创意与运行记录。导入前会自动保留数据库备份。</p><div class="row" style="margin-top:20px"><button onclick="exportAll()">导出完整工作空间</button><button onclick="$('#importfile').click()">导入迁移包</button><input type="file" id="importfile" accept=".json" hidden onchange="importAll(this)"></div><button style="margin-top:15px" onclick="showRuns()">查看运行记录</button></section><section class="card"><h2>设备规范 v0.1</h2><table class="table"><tr><td>显示</td><td>600×800 · 全彩光波导</td></tr><tr><td>FOV</td><td>30°，轴向待实机校准</td></tr><tr><td>布局</td><td>32px 安全区 / 8px 网格</td></tr><tr><td>正文 / 标题</td><td>32 / 40px</td></tr><tr><td>模拟边界</td><td>静态背景，无空间锚定</td></tr></table></section><section class="card"><h2>后续迭代清单</h2><p>${['01 钢笔与矢量路径','02 动画时间轴与关键帧','03 真实 OFN / 滚轴 / 手势 / HID','04 Camera 外设及视觉处理','05 正式 ASR / 实时字幕 / 翻译','06 正式 TTS 与字幕同步','07 光学参数与可读性校准','08 云端部署与迁移验证'].map(x=>'□ '+x).join('<br>')}</p></section></div></div>`}
function savePrefs(){localStorage.setItem('glasshouse-preferences',JSON.stringify(prefs))}
async function saveProvider(){prefs.provider=$('#provider').value;prefs.model=$('#model').value.trim();savePrefs();if($('#apiKey').value)await api('key',{provider:prefs.provider,key:$('#apiKey').value});await refresh();renderSettings();toast('连接配置已保存')}
async function saveSearchKey(){await api('key',{provider:'Tavily',key:$('#searchKey').value});await refresh();renderSettings();toast('检索密钥已保存在后台内存')}
function calendarDialog(){const today=new Date().toLocaleDateString('en-CA');modal('读取飞书测试日历',`<div class="notice">仅查询所选日历。建议输入你准备的测试日历 ID，避免混入私人日程。</div><label>日历 ID</label><input id="calid" placeholder="测试日历 ID；主日历请明确填写 primary"><div class="formgrid"><div><label>开始日期</label><input type="date" id="calstart" value="${today}"></div><div><label>结束日期</label><input type="date" id="calend" value="${today}"></div></div><div id="calresult" style="margin-top:15px"></div>`,`<button class="primary" id="readcal">读取日程</button>`);$('#readcal').onclick=()=>act(async()=>{$('#readcal').disabled=true;try{if(!$('#calid').value.trim())throw Error('请明确填写日历 ID；主日历请填写 primary');const r=await api('calendar',{calendarId:$('#calid').value,start:$('#calstart').value+'T00:00:00+08:00',end:$('#calend').value+'T23:59:59+08:00'});const items=normalizeEvents(r.result);simData=items;simSource='真实飞书日程';focusIndex=0;$('#calresult').innerHTML=`<div class="notice">成功读取并识别 ${items.length} 项日程</div><details><summary>查看返回数据</summary><pre class="log">${esc(JSON.stringify(r.result,null,2))}</pre></details>`;if(current&&page==='editor'){checkpoint();current.dataSnapshots={...current.dataSnapshots,calendar:{items,at:r.at,source:simSource}};current.dataSnapshot={type:'calendar',source:simSource,items,at:r.at};renderPreview();renderRight()}}finally{$('#readcal').disabled=false}})}
function normalizeEvents(value){const out=[];function walk(v){if(Array.isArray(v)){v.forEach(walk);return}if(!v||typeof v!=='object')return;if((v.summary||v.title)&&(v.start_time||v.start||v.startTime)){const t=v.start_time||v.start||v.startTime;let time=typeof t==='object'?(t.timestamp?new Date(Number(t.timestamp)*1000).toLocaleString('zh-CN'):t.datetime||t.date||t.date_time||''):String(t);const raw=typeof t==='object'?(t.timestamp?new Date(Number(t.timestamp)*1000):t.datetime||t.date_time||t.date):t;const dt=new Date(raw);const parts=Number.isNaN(dt.getTime())?null:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(dt).split(' ');const et=v.end_time||v.end||v.endTime;const ed=et?new Date(typeof et==='object'?(et.timestamp?Number(et.timestamp)*1000:et.datetime||et.date_time||et.date):et):null;out.push({id:v.event_id||v.id,status:v.status==='cancelled'?'cancelled':'normal',date:parts?.[0]||String(raw).slice(0,10),start:parts?.[1]||'',end:ed&&!Number.isNaN(ed.getTime())?new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}).format(ed):'',title:v.summary||v.title,time,location:typeof v.location==='object'?v.location?.name:v.location,description:v.description});return}Object.values(v).forEach(walk)}walk(value);return out}
function weatherDialog(){modal('天气连接 · Open-Meteo',`<p>通过指定坐标查询；默认示例为上海，不读取设备位置。</p><div class="formgrid"><div><label>纬度</label><input id="lat" type="number" value="31.23" step="0.01"></div><div><label>经度</label><input id="lon" type="number" value="121.47" step="0.01"></div></div><div id="weatherresult" style="margin-top:15px"></div>`,`<button class="primary" id="readweather">获取天气</button>`);$('#readweather').onclick=()=>act(async()=>{$('#readweather').disabled=true;try{const r=await api('weather',{lat:$('#lat').value,lon:$('#lon').value});simData=r.result;simSource=r.source;$('#weatherresult').innerHTML=`<div class="notice">${r.result.current.temperature_2m}° · 湿度 ${r.result.current.relative_humidity_2m}%<br>${esc(r.result.current.time)} · Open-Meteo</div>`;if(current&&page==='editor'){checkpoint();current.dataSnapshots={...current.dataSnapshots,weather:{data:r.result,at:r.at,source:r.source}};current.dataSnapshot={type:'weather',source:simSource,data:r.result,at:r.at};renderPreview();renderRight()}}finally{$('#readweather').disabled=false}})}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function exportAll(){download('glasshouse-workspace-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(await api('export'),null,2));toast('已导出持久化数据；未保存的画板修改请先保存')}
function importAll(input){const f=input.files[0];if(!f)return;modal('导入工作空间',`<p>将用 ${esc(f.name)} 替换当前工作空间。当前数据库会先保存为本地备份。</p>`,`<button onclick="closeModal()">取消</button><button class="primary" id="confirmimport">备份并导入</button>`);$('#confirmimport').onclick=()=>act(async()=>{let parsed;try{parsed=JSON.parse(await f.text())}catch{throw Error('备份文件不是有效的 JSON，请选择工作台导出的备份')}await api('import',parsed);await refresh();closeModal();current=null;go('home');toast('导入完成，原数据已备份')})}
async function showRuns(){const runs=await api('runs');modal('运行记录',runs.length?runs.map(r=>`<details class="step"><summary>${esc(r.type)} · ${esc(r.source||'')} · ${new Date(r.at*1000).toLocaleString()}</summary><pre class="log">${esc(JSON.stringify(r,null,2))}</pre></details>`).join(''):'暂无运行记录')}
function exportDemo(){const elements=current.elements.map(e=>`<div tabindex="${e.action&&e.action!=='none'?'0':'-1'}" style="position:absolute;left:${Number(e.x)}px;top:${Number(e.y)}px;width:${Number(e.w)}px;height:${Number(e.h)}px;font-size:${Number(e.fontSize)}px;color:${safeColor(e.color,'white')};background:${safeColor(e.background,'transparent')};border-radius:${Number(e.radius)||0}px;padding:${e.type==='card'?24:0}px;white-space:pre-wrap;overflow:hidden;box-sizing:border-box" onclick="this.style.outline=this.style.outline?'':'3px solid #ceef85'">${esc(boundText(e))}</div>`).join('');download(current.name+'.html',`<!doctype html><meta charset="utf-8"><title>${esc(current.name)}</title><body style="background:#e9eee3;font-family:sans-serif;display:grid;place-items:center"><p>${esc(current.name)} · 独立布局 Demo / 点击显示焦点，数据为导出时快照</p><main style="width:600px;height:800px;position:relative;background:linear-gradient(140deg,#455b45,#1b2c26 50%,#59624a)">${elements}</main></body>`,'text/html');toast('已导出独立布局 Demo，完整服务行为在工作台模拟器中运行')}
document.addEventListener('keydown',e=>{if(page!=='editor'||view!=='simulate'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||$('#modal').open)return;const map={ArrowDown:'next',ArrowRight:'next',ArrowUp:'prev',ArrowLeft:'prev',Enter:'confirm',Escape:'back'};if(map[e.key]){e.preventDefault();simEvent(map[e.key])}});
window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'操作失败');e.preventDefault()});
(async()=>{try{await refresh();if(!services().length){await createTemplate('calendar');page='home';current=null}render()}catch(e){$('#app').innerHTML='<div class="empty">无法连接本地服务：'+esc(e.message)+'</div>'}})();

function sampleEvents(){return [{title:'交互设计基础',time:'09:00 – 10:30',location:'设计楼 A301',description:'模拟课程 · 服务设计与可用性评估'},{title:'计算机视觉',time:'11:00 – 12:30',location:'实验楼 B202',description:'模拟课程 · 图像采集与特征识别'},{title:'产品创新工作坊',time:'14:00 – 16:00',location:'创意中心 C101',description:'模拟课程 · 小组原型评审'}]}
function editInputMapping(){const defaults={swipeUp:'prev',swipeDown:'next',swipeLeft:'back',swipeRight:'next',click:'confirm',press:'confirm',hold:'back',wheelUp:'prev',wheelDown:'next',shortcut:'back',pinch:'confirm',doublePinch:'back'};current.inputMapping=current.inputMapping||defaults;modal('设备输入映射',`<p>映射保存到当前服务。真实外设接入后复用这些语义动作。</p>${Object.entries(current.inputMapping).map(([k,v])=>`<div class="row" style="margin-top:8px"><span style="width:130px">${k}</span><select data-map="${k}">${['prev','next','confirm','back'].map(x=>`<option ${v===x?'selected':''}>${x}</option>`).join('')}</select><button onclick="dispatchInput('${k}')">模拟</button></div>`).join('')}`,`<button class="primary" id="saveMapping">保存映射</button>`);$('#saveMapping').onclick=()=>{checkpoint();$$('[data-map]').forEach(el=>current.inputMapping[el.dataset.map]=el.value);closeModal();toast('输入映射已保存到画板')};}
function dispatchInput(raw){const map=$(`[data-map="${raw}"]`)?.value||current.inputMapping?.[raw]||'confirm';simEvent(map);toast(raw+' → '+map)}
function poseEvent(value){$('#poseValue').textContent=value+'°';if($('#simlog'))$('#simlog').textContent='模拟姿态事件：roll '+value+'°（未默认绑定头部操作）';current.lastPose={roll:value,source:'模拟',at:Date.now()}}
function translateSimulation(){const original=$('#simtext').value||'今天的课程即将开始。';modal('双语字幕模拟',`<label>原文</label><textarea id="transOriginal">${esc(original)}</textarea><label>模拟译文（手动提供，不是真实翻译）</label><textarea id="transTarget">The class is about to begin.</textarea>`,`<button class="primary" id="playTranslation">播放模拟语段</button>`);$('#playTranslation').onclick=()=>{const a=$('#transOriginal').value,b=$('#transTarget').value;closeModal();if(!current.elements.some(e=>e.binding==='caption')){checkpoint();current.elements.push({...baseElements('','')[2],id:uid(),binding:'caption',y:480,h:260})}clearInterval(streamTimer);let i=0;simSource='模拟双语字幕 · 手动译文';streamTimer=setInterval(()=>{i++;simData=a.slice(0,i)+'\n'+b.slice(0,Math.ceil(i*b.length/a.length));renderPreview();if(i>=a.length)clearInterval(streamTimer)},100);renderRight()}}
function runSimulation(){const nodes=current.nodes.filter(n=>n.mode!=='optional'),ids=new Set(nodes.map(n=>n.id));const edges=current.edges.filter(e=>ids.has(e.from)&&ids.has(e.to)),pending=new Map(nodes.map(n=>[n.id,edges.filter(e=>e.to===n.id).length]));const queue=nodes.filter(n=>pending.get(n.id)===0),order=[];while(queue.length){const n=queue.shift();order.push(n);for(const e of edges.filter(e=>e.from===n.id)){pending.set(e.to,pending.get(e.to)-1);if(pending.get(e.to)===0)queue.push(nodes.find(n=>n.id===e.to))}}if(order.length!==nodes.length)return toast('流程包含循环；请拆开循环再模拟');if(!nodes.length)return toast('先添加必选能力');const rows=order.map((n,i)=>({step:i+1,name:n.snapshot.name,input:n.snapshot.input,output:n.snapshot.output,mode:'模拟',config:n.config||'未定义策略',at:new Date().toISOString()}));checkpoint();current.lastSimulation={rows,at:Date.now(),source:'拓扑顺序模拟，未执行外部副作用'};view='simulate';if(current.template==='calendar'&&!simData)simData=sampleEvents();renderEditor();modal('流程模拟记录',`<div class="notice">按依赖顺序模拟 ${rows.length} 个必选节点。备选节点不执行；真实日历与天气需在预览控制台单独读取。</div>${rows.map(r=>`<div class="step"><b>${r.step}. ${esc(r.name)}</b><p>${esc(r.input)} → ${esc(r.output)}</p><small>${esc(r.config)} · 模拟</small></div>`).join('')}`)}

function editMockData(){modal('编辑模拟数据',`<p>JSON 数组支持 title、time、location、description；用于 calendar 数据绑定。</p><textarea id="mockjson" style="height:300px;font-family:monospace">${esc(JSON.stringify(Array.isArray(simData)?simData:sampleEvents(),null,2))}</textarea>`,`<button class="primary" id="applyMock">应用模拟数据</button>`);$('#applyMock').onclick=()=>act(()=>{let items;try{items=JSON.parse($('#mockjson').value)}catch{throw Error('模拟数据格式错误，请输入有效的 JSON 数组')}if(!Array.isArray(items)||items.some(x=>typeof x.title!=='string'))throw Error('请输入包含 title 的数组');checkpoint();simData=items;simSource='用户模拟数据';current.dataSnapshot={type:'calendar',source:simSource,items,at:Date.now()/1000};focusIndex=0;closeModal();renderPreview();renderRight()})}

function labelControls(root){root.querySelectorAll('label').forEach(label=>{const field=label.nextElementSibling;if(!label.htmlFor&&!label.querySelector('input,select,textarea')&&field?.matches('input,select,textarea')){field.id=field.id||'field-'+uid();label.htmlFor=field.id}});const names={none:'无动作',detail:'查看详情',back:'返回',next:'下一项',prev:'上一项',confirm:'确认',calendar:'日历',weather:'天气',caption:'字幕',date:'日期',camera:'相机'};root.querySelectorAll('option').forEach(o=>{if(names[o.textContent]){const value=o.value;o.textContent=names[o.textContent];o.value=value}})}
